private val scheduleNames=listOf("daily" to "每天","weekdays" to "工作日","weekly" to "每周","once" to "仅一次","cron" to "自定义","manual" to "手动触发")
private val weekNames=listOf("monday" to "周一","tuesday" to "周二","wednesday" to "周三","thursday" to "周四","friday" to "周五","saturday" to "周六","sunday" to "周日")
private fun coaxiScheduleLabel(schedule:JsonObject):String=when(schedule.coreText("kind")){"manual"->"手动触发";"daily"->"每天 "+schedule.coreText("at");"weekdays"->"工作日 "+schedule.coreText("at");"weekly"->"每周 "+(weekNames.firstOrNull{it.first==schedule.coreText("weekday")}?.second?:"")+" "+schedule.coreText("at");"once"->schedule.coreText("date")+" "+schedule.coreText("at");"cron"->"自定义 · "+schedule.coreText("expression");else->"未识别的计划"}
/** Coaxi AutomationWorkspace/Editor fields and history using Coaxi native GlassRow. */
@Composable
fun CoaxiAutomationSettings(model:CoaxiWorkspaceViewModel,onOpenThread:(String)->Unit){
    val state by model.state.collectAsStateWithLifecycle();val scope=rememberCoroutineScope()
    var entries by remember{mutableStateOf<List<JsonObject>>(emptyList())};var cursor by remember{mutableStateOf<String?>(null)};var filter by remember{mutableStateOf("all")};var search by remember{mutableStateOf("")}
    var selected by remember{mutableStateOf<JsonObject?>(null)};var creating by remember{mutableStateOf(false)};var busy by remember{mutableStateOf(false)};var issue by remember{mutableStateOf<String?>(null)};var confirm by remember{mutableStateOf<Pair<CoaxiOperation,JsonObject>?>(null)}
    var history by remember{mutableStateOf<JsonObject?>(null)};var runs by remember{mutableStateOf<List<JsonObject>>(emptyList())};var runCursor by remember{mutableStateOf<String?>(null)}
    suspend fun load(after:String?=null){busy=true;try{val value=model.query(CoaxiOperation.AUTOMATIONS_LIST,buildJsonObject{put("status",filter);put("query",search);put("limit",30);after?.let{put("cursor",it)}}).coreObject();entries=if(after==null)value["automations"].coreArray()else entries+value["automations"].coreArray();cursor=(value["nextCursor"] as? JsonPrimitive)?.contentOrNull;issue=null}catch(cancelled:CancellationException){throw cancelled}catch(error:Exception){issue=error.message}finally{busy=false}}
    suspend fun readRuns(item:JsonObject,after:String?=null){busy=true;try{val value=model.query(CoaxiOperation.AUTOMATIONS_RUNS_LIST,buildJsonObject{put("automationId",item.coreText("automationId"));put("limit",20);after?.let{put("cursor",it)}}).coreObject();runs=if(after==null)value["runs"].coreArray()else runs+value["runs"].coreArray();runCursor=(value["nextCursor"] as? JsonPrimitive)?.contentOrNull;history=item;issue=null}catch(cancelled:CancellationException){throw cancelled}catch(error:Exception){issue=error.message}finally{busy=false}}
    LaunchedEffect(filter,state.lastResult,state.resourceVersion){delay(250);if(!creating&&selected==null)load();history?.let{readRuns(it)}}
    if(creating||selected!=null){CoaxiAutomationEditor(model,selected,onOpenThread=onOpenThread,onSaved={selected=null;creating=false},onClose={selected=null;creating=false});return}
    Column(Modifier.fillMaxSize().padding(16.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){
        Row{Text(stringResource(R.string.coaxi_fusion_3c39e9bde120ddb5),style=MaterialTheme.typography.titleLarge,modifier=Modifier.weight(1f));TextButton(enabled=state.pending==null,onClick={creating=true}){Text(stringResource(R.string.coaxi_fusion_50ef2f4cf6a46924))}}
        issue?.let{Text(it,color=CoaxiTheme.colors.danger)};if(busy)LinearProgressIndicator(Modifier.fillMaxWidth())
        if(history!=null){Row{Text(history!!.coreText("name"),Modifier.weight(1f));TextButton(onClick={history=null;runs=emptyList()}){Text(stringResource(R.string.coaxi_fusion_e9d5ca6c140665da))}};LazyColumn(Modifier.weight(1f),verticalArrangement=Arrangement.spacedBy(8.dp)){items(runs,key={it.coreText("runId")}){run->GlassRow{Text(run.coreText("scheduledFor"));Text(run.coreText("status"),color=CoaxiTheme.colors.textSecondary);if(run.coreText("reason").isNotEmpty())Text(run.coreText("reason"));Row{if(run.coreText("threadId").isNotEmpty())TextButton(onClick={onOpenThread(run.coreText("threadId"))}){Text(stringResource(R.string.coaxi_fusion_d3a00c2dc2936a2e))};if(run.coreText("status") in listOf("running","cancelling"))TextButton(enabled=state.pending==null,onClick={confirm=CoaxiOperation.AUTOMATIONS_CANCELRUN to buildJsonObject{put("automationId",history!!.coreText("automationId"));put("runId",run.coreText("runId"))}}){Text(stringResource(R.string.coaxi_fusion_95ed87bcf431c5c6))}}}};runCursor?.let{after->item{TextButton(enabled=!busy,onClick={scope.launch{readRuns(history!!,after)}}){Text(stringResource(R.string.coaxi_fusion_fbb9d47cf98c790f))}}}}}
        else{
            OutlinedTextField(search,{search=it},label={Text(stringResource(R.string.coaxi_fusion_5d02c355dcc5bc82))},modifier=Modifier.fillMaxWidth(),trailingIcon={TextButton(enabled=!busy,onClick={scope.launch{load()}}){Text(stringResource(R.string.coaxi_fusion_44ce7ae909bbb28b))}})
            Row(Modifier.horizontalScroll(rememberScrollState())){listOf("all" to "全部","enabled" to "启用","closed" to "已关闭").forEach{(id,label)->FilterChip(selected=filter==id,onClick={filter=id},label={Text(label)})}}
            LazyColumn(Modifier.weight(1f),verticalArrangement=Arrangement.spacedBy(10.dp)){items(entries,key={it.coreText("automationId")}){item->GlassRow{Text(item.coreText("name"),style=MaterialTheme.typography.titleMedium);Text(item.coreText("prompt"),maxLines=3);Text(coaxiScheduleLabel(item["schedule"].coreObject()),color=CoaxiTheme.colors.textSecondary);Text(stringResource(R.string.coaxi_fusion_a856dbc1a170ca3f)+item.coreText("nextRunAt"),style=MaterialTheme.typography.labelSmall);Row(Modifier.horizontalScroll(rememberScrollState())){TextButton(enabled=state.pending==null,onClick={selected=item}){Text(stringResource(R.string.coaxi_fusion_051836569928a9f9))};TextButton(enabled=!busy,onClick={scope.launch{readRuns(item)}}){Text(stringResource(R.string.coaxi_fusion_6e55e0f207bfd2e0))};TextButton(enabled=state.pending==null,onClick={confirm=CoaxiOperation.AUTOMATIONS_RUN to buildJsonObject{put("automationId",item.coreText("automationId"))}}){Text(stringResource(R.string.coaxi_fusion_04eb539709cf130d))};TextButton(enabled=state.pending==null,onClick={confirm=(if(item["enabled"]==JsonPrimitive(true))CoaxiOperation.AUTOMATIONS_CLOSE else CoaxiOperation.AUTOMATIONS_UPDATE) to buildJsonObject{put("automationId",item.coreText("automationId"));put("expectedVersion",item.coreLong("version"));if(item["enabled"]!=JsonPrimitive(true))put("enabled",true)}}){Text(if(item["enabled"]==JsonPrimitive(true))"关闭" else "启用")};TextButton(enabled=state.pending==null,onClick={confirm=CoaxiOperation.AUTOMATIONS_DELETE to buildJsonObject{put("automationId",item.coreText("automationId"));put("expectedVersion",item.coreLong("version"))}}){Text(stringResource(R.string.coaxi_fusion_2f9daa828907b93f))}}}};cursor?.let{after->item{TextButton(enabled=!busy,onClick={scope.launch{load(after)}}){Text(stringResource(R.string.coaxi_fusion_af90a08fec8ee28d))}}}}
        }
    }
    confirm?.let{action->AlertDialog(onDismissRequest={confirm=null},title={Text(if(action.first==CoaxiOperation.AUTOMATIONS_RUN)"立即运行此任务？"else if(action.first==CoaxiOperation.AUTOMATIONS_DELETE)"删除定时任务？"else if(action.first==CoaxiOperation.AUTOMATIONS_CANCELRUN)"停止所选运行？"else"修改任务启用状态？")},text={Text(if(action.first==CoaxiOperation.AUTOMATIONS_RUN)"按此计划保存的执行方式处理；生成使命时不会启动队员。"else"按当前所选任务和版本执行；运行结果仍保留在原对话中。")},confirmButton={TextButton(enabled=state.pending==null&&!state.busy,onClick={model.command(action.first,action.second);confirm=null}){Text(stringResource(R.string.coaxi_fusion_36f33adaf0942634))}},dismissButton={TextButton(onClick={confirm=null}){Text(stringResource(R.string.coaxi_fusion_2cd0f3be8738a86c))}})}
}
@Composable
private fun CoaxiAutomationEditor(model:CoaxiWorkspaceViewModel,original:JsonObject?,onOpenThread:(String)->Unit,onSaved:()->Unit,onClose:()->Unit){
    val state by model.state.collectAsStateWithLifecycle();val scope=rememberCoroutineScope();val id=original?.coreText("automationId")?:"new";val owner="automation-draft:$id"
    var name by remember(id){mutableStateOf(original?.coreText("name")?:"")};var prompt by remember(id){mutableStateOf(original?.coreText("prompt")?:"")};var member by remember(id){mutableStateOf(original?.coreText("memberId")?:"")};var path by remember(id){mutableStateOf(original?.get("projectRef").coreObject().coreText("path"))}
    var kind by remember(id){mutableStateOf(original?.get("schedule").coreObject().coreText("kind").ifEmpty{"daily"})};var at by remember(id){mutableStateOf(original?.get("schedule").coreObject().coreText("at").ifEmpty{"09:00"})};var date by remember(id){mutableStateOf(original?.get("schedule").coreObject().coreText("date"))};var weekday by remember(id){mutableStateOf(original?.get("schedule").coreObject().coreText("weekday").ifEmpty{"monday"})};var cron by remember(id){mutableStateOf(original?.get("schedule").coreObject().coreText("expression"))}
    var channels by remember(id){mutableStateOf((original?.get("notifyChannels") as? JsonArray)?.map{it.jsonPrimitive.content}?.toSet()?:emptySet())};var ready by remember(id){mutableStateOf(false)};var issue by remember{mutableStateOf<String?>(null)};var sent by remember{mutableStateOf<String?>(null)}
    var definitionVersion by remember(id){mutableLongStateOf(original?.coreLong("version")?:0L)}
    fun draft():JsonObject=buildJsonObject{put("name",name);put("prompt",prompt);put("memberId",member);put("path",path);put("kind",kind);put("at",at);put("date",date);put("weekday",weekday);put("cron",cron);put("channels",JsonArray(channels.map(::JsonPrimitive)))}
    LaunchedEffect(id){try{val raw=model.readBody(owner);if(raw.isNotEmpty()){val value=Json.parseToJsonElement(raw).coreObject();name=value.coreText("name");prompt=value.coreText("prompt");member=value.coreText("memberId");path=value.coreText("path");kind=value.coreText("kind");at=value.coreText("at");date=value.coreText("date");weekday=value.coreText("weekday");cron=value.coreText("cron");channels=value["channels"]?.jsonArray?.map{it.jsonPrimitive.content}?.toSet()?:emptySet()};ready=true}catch(error:Exception){issue=error.message}}
    val current=draft().toString();LaunchedEffect(current,ready){if(ready)try{model.saveBody(owner,current)}catch(error:Exception){issue=error.message}}
    LaunchedEffect(state.lastResult){val receipt=state.lastResult.coreObject()["commandResult"].coreObject().ifEmpty{state.lastResult.coreObject()};if(sent!=null&&receipt.coreText("commandId")==sent&&receipt.coreText("status") in listOf("applied","accepted")){model.saveBody(owner,"");onSaved()}}
    val blocked=!ready||state.pending!=null||state.busy
    LazyColumn(Modifier.fillMaxSize().padding(16.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){
        item{Row{Text(if(original==null)"新建定时任务"else"编辑定时任务",Modifier.weight(1f),style=MaterialTheme.typography.titleLarge);TextButton(onClick=onClose){Text(stringResource(R.string.coaxi_fusion_2963c07fcb0b9ae5))}};issue?.let{Text(it,color=CoaxiTheme.colors.danger)}}
        item{OutlinedTextField(name,{name=it},label={Text(stringResource(R.string.coaxi_fusion_d44e9b3d3b31d37b))},enabled=!blocked,modifier=Modifier.fillMaxWidth());OutlinedTextField(prompt,{prompt=it},label={Text(stringResource(R.string.coaxi_fusion_2b7e32bffda6dfb8))},enabled=!blocked,minLines=4,modifier=Modifier.fillMaxWidth())}
        item{Text(stringResource(R.string.coaxi_fusion_3145f4be5ae68ad4));state.members.filter{it.coreText("presence")=="present"}.forEach{agent->Row{RadioButton(selected=member==agent.coreText("agentId"),enabled=!blocked,onClick={member=agent.coreText("agentId")});Text(agent.coreText("displayName"))}};Text(stringResource(R.string.coaxi_fusion_3db7b06b5f6de0e0));Row{RadioButton(selected=path.isEmpty(),enabled=!blocked,onClick={path=""});Text(stringResource(R.string.coaxi_fusion_7b0df27853e6f545))};state.navigation["projects"].coreArray().forEach{project->Row{RadioButton(selected=path==project.coreText("projectPath"),enabled=!blocked,onClick={path=project.coreText("projectPath")});Text(project.coreText("name"))}}}
        item{Row(Modifier.horizontalScroll(rememberScrollState())){scheduleNames.forEach{(value,label)->FilterChip(selected=kind==value,enabled=!blocked,onClick={kind=value},label={Text(label)})}};if(kind !in listOf("manual","cron"))OutlinedTextField(at,{at=it},label={Text(stringResource(R.string.coaxi_fusion_36fa40ea9029429a))},enabled=!blocked);if(kind=="once")OutlinedTextField(date,{date=it},label={Text(stringResource(R.string.coaxi_fusion_2132a2750b5494b5))},enabled=!blocked);if(kind=="weekly")Row(Modifier.horizontalScroll(rememberScrollState())){weekNames.forEach{(value,label)->FilterChip(selected=weekday==value,enabled=!blocked,onClick={weekday=value},label={Text(label)})}};if(kind=="cron")OutlinedTextField(cron,{cron=it},label={Text(stringResource(R.string.coaxi_fusion_8d38730aeb8e0d61))},enabled=!blocked)}
        if(original!=null)item{key(id,model.connectionGeneration){CoaxiAutomationConversationDetails(model,id,!blocked,onVersionChange={definitionVersion=it},onOpenThread=onOpenThread)}}
        item{Text(stringResource(R.string.coaxi_fusion_41bf962d939c38a3));listOf("feishu" to "飞书","lark" to "Lark","dingtalk" to "钉钉").forEach{(value,label)->Row{Checkbox(checked=value in channels,enabled=!blocked,onCheckedChange={channels=if(it)channels+value else channels-value});Text(label)}}}
        item{Button(enabled=!blocked&&prompt.isNotBlank()&&member.isNotEmpty(),onClick={scope.launch{try{if(kind !in listOf("manual","cron"))require(Regex("([01][0-9]|2[0-3]):[0-5][0-9]").matches(at)){"请填写有效时间"};if(kind=="once")java.time.LocalDate.parse(date);if(kind=="cron")require(cron.trim().split(Regex("\\s+")).size==5){"Cron需要5个字段"};model.saveBody(owner,current);val command=buildJsonObject{if(original!=null){put("automationId",id);put("expectedVersion",definitionVersion)};put("name",name);put("prompt",prompt);put("memberId",member);putJsonObject("projectRef"){put("kind",if(path.isEmpty())"quick_chat"else"directory");if(path.isNotEmpty())put("path",path)};putJsonObject("schedule"){put("kind",kind);if(kind !in listOf("manual","cron"))put("at",at);if(kind=="once")put("date",date);if(kind=="weekly")put("weekday",weekday);if(kind=="cron")put("expression",cron)};put("notifyChannels",JsonArray(channels.map(::JsonPrimitive)))};val commandId=UUID.randomUUID().toString();sent=commandId;model.execute(if(original==null)CoaxiOperation.AUTOMATIONS_CREATE else CoaxiOperation.AUTOMATIONS_UPDATE,buildJsonObject{put("commandId",commandId);put("command",command)})}catch(error:Exception){issue=error.message}}}){Text(stringResource(R.string.coaxi_fusion_24a015d6239c33c8))}}
    }
}
